insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$ASE$q$,$q$public_company$q$),($q$Alpha Wave$q$,$q$private_company$q$),($q$AlphaSense$q$,$q$private_company$q$),($q$Benchmark$q$,$q$private_company$q$),($q$Eclipse$q$,$q$private_company$q$),($q$Fidelity$q$,$q$private_company$q$),($q$Foundation Capital$q$,$q$private_company$q$),($q$G42$q$,$q$private_company$q$),($q$GSK$q$,$q$public_company$q$),($q$Hugging Face$q$,$q$private_company$q$),($q$IBM$q$,$q$public_company$q$),($q$MBZUAI$q$,$q$other$q$),($q$OpenAI$q$,$q$private_company$q$),($q$OpenRouter$q$,$q$private_company$q$),($q$U.S. Department of Defense$q$,$q$government$q$),($q$Vercel$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
