create function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Intel$q$ then ticker=$q$INTC$q$ when $q$Oracle$q$ then ticker=$q$ORCL$q$ when $q$AMD$q$ then ticker=$q$AMD$q$ when $q$CoreWeave$q$ then ticker=$q$CRWV$q$ when $q$TSMC$q$ then ticker=$q$TSM$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$Uber Eats$q$ then ticker=$q$UBER$q$ when $q$CBRS$q$ then ticker=$q$CBRS$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$CBRS M6 group 1$q$,'claude-sonnet-5-5',471940,16348,1.5437,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/0002021728/000162828026035214/cerebras-424b4.htm$q$,r.sec[k],t,true,$q$2026-05-14$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;

